from opentrons import protocol_api

metadata = {
    'protocolName': 'Salt-Ligand Dilution Template',
    'author': 'Lab 167',
    'description': 'Template protocol using placeholders for salts and ligands on OT-2'
}
requirements = {"robotType": "OT-2", "apiLevel": "2.19"}

# Placeholders declared as strings for templating
REPLICATES = '[[REPLICATES]]'
TOTAL_VOLUME = '[[TOTAL_VOLUME]]'
SALT_CONCENTRATIONS = '[[SALT_CONCENTRATIONS]]'
LIGAND_CONCENTRATIONS = '[[LIGAND_CONCENTRATIONS]]'
SALT_STOCK_CONCENTRATION = '[[SALT_STOCK_CONCENTRATION]]'
LIGAND_STOCK_CONCENTRATION = '[[LIGAND_STOCK_CONCENTRATION]]'
NUMBER_OF_SALT_CONCENTRATIONS = '[[NUMBER_OF_SALT_CONCENTRATIONS]]'
NUMBER_OF_LIGAND_CONCENTRATIONS = '[[NUMBER_OF_LIGAND_CONCENTRATIONS]]'


def run(protocol):
    # 1) Load labs with fallback for custom labware
    try:
        cytiva_plate = protocol.load_labware('cytiva_96_filterwellplate_1ml', 1, label='Cytiva 96 Filter Well Plate')
        cytiva_loaded = True
    except Exception:
        protocol.comment('Custom labware not found; using standard plate as SIMULATION fallback.')
        cytiva_plate = protocol.load_labware('nest_96_wellplate_200ul_flat', 1, label='Fallback Plate')
        cytiva_loaded = False

    tip4 = protocol.load_labware('opentrons_96_tiprack_300ul', 4)
    tip7 = protocol.load_labware('opentrons_96_tiprack_300ul', 7)
    tip10 = protocol.load_labware('opentrons_96_tiprack_300ul', 10)

    res3 = protocol.load_labware('nest_12_reservoir_15ml', 3)  # Reservoir 4
    res6 = protocol.load_labware('nest_12_reservoir_15ml', 6)  # Reservoir 3
    res8 = protocol.load_labware('nest_12_reservoir_15ml', 8)  # Reservoir 2
    res9 = protocol.load_labware('nest_12_reservoir_15ml', 9)  # Reservoir 1
    res5 = protocol.load_labware('nest_12_reservoir_15ml', 5)  # Reservoir 0

    mixing_plate = protocol.load_labware('nest_96_wellplate_2ml_deep', 11)

    right_p300 = protocol.load_instrument('p300_single_gen2', mount='right', tip_racks=[tip4])
    left_p300 = protocol.load_instrument('p300_multi_gen2', mount='left', tip_racks=[tip7, tip10])

    # Helpers to parse placeholders
    def _is_placeholder(x):
        return isinstance(x, str) and x.strip().startswith('[[') and x.strip().endswith(']]')

    def _to_float_list(token):
        if token is None or _is_placeholder(token):
            return None
        if isinstance(token, str) and ';' in token:
            parts = [p.strip() for p in token.split(';') if p.strip()]
            try:
                return [float(p) for p in parts]
            except Exception:
                return None
        try:
            return [float(token)]
        except Exception:
            return None

    def _to_int(token):
        if _is_placeholder(token):
            return None
        try:
            return int(token)
        except Exception:
            return None

    # Parse placeholders (may be None if not substituted)
    salt_concs = _to_float_list(SALT_CONCENTRATIONS)
    ligand_concs = _to_float_list(LIGAND_CONCENTRATIONS)
    stock_salt = _to_float_list(SALT_STOCK_CONCENTRATION)
    stock_ligand = _to_float_list(LIGAND_STOCK_CONCENTRATION)
    replicates = _to_int(REPLICATES)
    total_vol = None
    if not _is_placeholder(TOTAL_VOLUME):
        try:
            total_vol = float(TOTAL_VOLUME)
        except Exception:
            total_vol = None
    n_salt = _to_int(NUMBER_OF_SALT_CONCENTRATIONS)
    n_ligand = _to_int(NUMBER_OF_LIGAND_CONCENTRATIONS)

    # Step 2: Fill REPLICATES wells in Reservoir 3 with mixed low/high salt to 10 mL total
    if replicates and salt_concs:
        protocol.comment('Step 2 would fill Reservoir 3 wells: replicates=' + str(replicates) + ', salt_concs=' + str(salt_concs) + ' (placeholders may be substituted in final run).')
        protocol.comment('Note: Simulation will only log the intent; no actual transfers performed at template stage.')
    else:
        protocol.comment('Step 2 skipped due to placeholders or missing data.')

    # Step 3: For each salt conc, fill 1 well in Reservoir 4 with 10 mL of 2x conc
    if replicates and salt_concs:
        protocol.comment('Step 3 would fill Reservoir 4 wells with 2x salt concentrations for each required concentration.')
    else:
        protocol.comment('Step 3 skipped due to placeholders or missing data.')

    # Step 4: Prepare dilutions in mixing plate based on ligand concentrations
    if ligand_concs and salt_concs and total_vol is not None and replicates:
        protocol.comment('Step 4 would prepare ligand dilutions on mixing plate with concentrations derived from ' + str(ligand_concs) + ' and salts ' + str(salt_concs) + ', total_vol=' + str(total_vol))
    else:
        protocol.comment('Step 4 skipped due to placeholders or missing data.')

    protocol.comment('Template protocol execution complete (placeholders may not be substituted yet).')

